package fr.skyframe.lms.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;

/**
 * Describes a file kept in the file store (MongoDB GridFS). Only this metadata lives in the relational
 * database; the bytes themselves are in GridFS under {@code storageKey}.
 *
 * Embedded into the entity that owns the file (e.g. Submission), so its columns are part of
 * that entity's table. If there is no file, all columns are null.
 */
@Embeddable
public class FileReference {

    /** Where the bytes are in the file store. Generated by us, never derived from the user's file name. */
    @Column(name = "file_storage_key")
    private String storageKey;

    /** The name the file had on the user's computer, used when downloading. */
    @Column(name = "file_name")
    private String originalFilename;

    @Column(name = "file_content_type")
    private String contentType;

    @Column(name = "file_size")
    private Long size;

    protected FileReference() {
        // for JPA
    }

    public FileReference(String storageKey, String originalFilename, String contentType, long size) {
        this.storageKey = storageKey;
        this.originalFilename = originalFilename;
        this.contentType = contentType;
        this.size = size;
    }

    public String getStorageKey() {
        return storageKey;
    }

    public String getOriginalFilename() {
        return originalFilename;
    }

    public String getContentType() {
        return contentType;
    }

    public Long getSize() {
        return size;
    }
}
